function protectedDefault() {
    counts.factory += 1;
    events.push({
      phase: "default",
      arguments: observe([...arguments]),
      thisIsDeclaration: this === field,
      thisType: typeof this
    });
    switch (scenario.result) {
      case "string":
        return "factory-value";
      case "undefined":
        return;
      case "date":
        return new Date(protectedFunctionDate);
      case "object":
        return { source: "factory", ownUndefined: void 0 };
      case "function":
        return returnedFunction;
      case "throws":
        throw Error("protected-default-failed");
      default:
        throw Error(`Unknown factory result: ${scenario.result}`);
    }
  }

